head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS05200.xml";
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "3";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp;
scwin.vSelObj;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_list_sync
 * 설명       : 신청/접수 목록을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 일괄상장 연간 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //종목정보체크
    if (scwin.fn_CheckEach() > 0) return;
    var hasAttachDoc = dts_List.getCellData(1, "HAS_ATTACH_DOC");
    if (scwin.processGp == '1') {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '접수')) return;
    } else {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '수정')) return;
    }

    //발행방법설정
    var ISU_METHD_INDIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_INDIRECT');
    var ISU_METHD_DIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_DIRECT');
    var ISU_METHD_PPBOND = dts_IsuInfo.getCellData(1, 'ISU_METHD_PPBOND');
    dts_IsuInfo.setCellData(1, 'BND_ISU_METHD_CD', ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND);

    //탭 데이터셋 설정
    scwin.fn_SetCreditData();

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    var url = "/bns/PackList.do?method=processAcptByyy";
    if (scwin.processGp == '2') {
        url = "/bns/PackList.do?method=updateAcptByyy";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    var dsKeyValue = "JSP(";
    dsKeyValue += "I:pInput=dts_IsuInfo";
    dsKeyValue += ", I:pInput1=dts_Credit";
    dsKeyValue += ", I:pInput8=dts_SplitRedmpt";
    dsKeyValue += ")";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = dsKeyValue;
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetMktactCd
 * 설명       : 신규상장 채권시장조치구분코드를 설정한다.
 ***********************************************/
scwin.fn_SetMktactCd = function() {
    scwin.vMktactCd = "112122132";
};


/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += '&{P}V_BND_APPL_ID=' + scwin.vBndApplId; //채권신청ID
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listCredit';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var param = '';
    param += '&{P}V_INST_NM=';
    var dsNm = 'BNS_INST_INFO';
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
    }); //발행통화				
    arrCid.push({
        cid: '01422',
        cnm: 'cmb_BndTpCd'
    }); //채권유형				
    arrCid.push({
        cid: '03076',
        cnm: 'cmb_MunibndTpCd'
    }); //지방채구분				
    arrCid.push({
        cid: '03221',
        cnm: 'cmb_NusualBndTpCd'
    }); //특이채권유형			
    arrCid.push({
        cid: '03055',
        cnm: 'cmb_BndGuarTpCd'
    }); //보증/담보				
    arrCid.push({
        cid: '00872',
        cnm: 'cmb_IntPayMethdCd'
    }); //이자지급방법			
    arrCid.push({
        cid: '03053',
        cnm: 'cmb_DebtRepayRankTpCd'
    }); //선/후/중순위			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyPrincPayDdDecsnCd'
    }); //휴무관련(원금)			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
    }); //이자일지급구분			
    arrCid.push({
        cid: '03512',
        cnm: 'cmb_IntUdwonProcsCd'
    }); //이자원단위 미만처리		
    arrCid.push({
        cid: '03114',
        cnm: 'cmb_BndOddllotddIntBasTpCd'
    }); //단수일 이자기준			
    arrCid.push({
        cid: '01510',
        cnm: 'cmb_BndSaleTpCd'
    }); //매출형태				
    arrCid.push({
        cid: '02253',
        cnm: 'cmb_IntMmendTpCd'
    }); //이자월말구분			
    arrCid.push({
        cid: '01562',
        cnm: 'cmb_BndPreSaleIntPayMethdCd'
    }); //선매출시 이자지급방법	
    arrCid.push({
        cid: '03454',
        cnm: 'cmb_BndApctTpCd'
    }); //신청인구분				
    arrCid.push({
        cid: '03085',
        cnm: 'cmb_SplitRedmptTpCd'
    }); //분할상환구분	
    arrCid.push({
        cid: '03051',
        cnm: 'cmb_RedmptPdIntTpCd'
    }); //거치기간이자	
    $c.bns.fn_SetBnsComboToCode(scwin.vScrenID, dts_Temp, arrCid);
};


/********************************************** 
 * 함수명   : fn_GetParCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_IsuInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_IsuInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParReturn
 * 설명       : 반송 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    var initTpCd = '0';
    //관련기관-대표주관회사
    if (scwin.vSelObj.id == 'cmb_BndMajagntComCd') {
        initTpCd = '1';
    }
    //관련기관-보증기관
    else if (scwin.vSelObj.id == 'cmb_GrtInstCd') {
        initTpCd = '2';
    }
    //관련기관-등록기관
    else if (scwin.vSelObj.id == 'cmb_RegInstCd') {
        initTpCd = '3';
    }
    //관련기관-원리금지급대행
    else if (scwin.vSelObj.id == 'cmb_PrincintPayAgntCd') {
        initTpCd = '4';
    }
    //관련기관-수탁기관
    else if (scwin.vSelObj.id == 'cmb_TrstInstCd') {
        initTpCd = '5';
    }
    arrPar[0] = {
        INST_CD: '',
        INST_NM: '',
        LBL_NM: '',
        INIT_TP_CD: initTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].INST_CD);
};


/********************************************** 
 * 함수명   : fn_ShowInst
 * 설명       : 기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowInst = function(selObj) {
    if (scwin.vRowCount == 0) return;
    scwin.vSelObj = selObj;
    scwin.fn_GetPar = fn_GetParInst;
    scwin.fn_SetPar = fn_SetParInst;
    $c.bns.fn_PopInstSearch(selObj);
};


/********************************************** 
 * 함수명   : fn_SetCreditCombo
 * 설명       : 신용평가기관을 설정한다.
 ***********************************************/
scwin.fn_SetCreditCombo = function(obj, cd, val) {
    var cbdata = "^ ," + cd + "^" + val;
    obj.CBData = cbdata;
    $c.stf.setObjectValue(obj, cd);
};


/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가 데이터셋 설정
 ***********************************************/
scwin.fn_SetCreditData = function() {
    dts_Credit.removeAll();
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd1) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd1));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd1));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn1));
    }
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd2) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd2));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd2));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn2));
    }
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd3) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd3));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd3));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn3));
    }
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd4) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd4));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd4));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn4));
    }
};



/********************************************** 
 * 함수명   : fn_MinusGumriOK
 * JACKAL_191129
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_MinusGumriOK = function(obj, msg) {
    var obj_rt = $c.stf.getObjectValue(obj);
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            //setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};




/********************************************** 
* 함수명   : fn_MinusGumriCheck
* JACKAL_191129
* 설명       : 개별 체크한다.
edt_CoupnRt COUPN_RT
edt_ScbdInt SCBD_INT
edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT
edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT
edt_GrtYd GRT_YD
edt_AddYd ADD_YD
***********************************************/
scwin.fn_MinusGumriCheck = function() {
    if (!scwin.fn_MinusGumriOK(edt_CoupnRt, '표면이자율') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_GrtYd, '보장수익률') &&
        !scwin.fn_MinusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};


/********************************************** 
 * 함수명   : fn_CheckEach
 * 설명       : 개별정보를 체크한다.
 ***********************************************/
scwin.fn_CheckEach = function() {
    // 마이너스 금리 체크
    if (!scwin.fn_MinusGumriCheck()) return 1; // JACKAL_191129

    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") == '') {
        $c.win.alert("채권유형을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") == "MB" && dts_IsuInfo.getCellData(1, "MUNIBND_TP_CD") == '') {
        $c.win.alert("지방채구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "NUSUAL_BND_TP_CD") == '') {
        $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "INT_PAY_METHD_CD") == '') {
        $c.win.alert("이자지급방법을 선택하십시오.");
        return 1;
    }
    /* 확인 */
    if (dts_IsuInfo.getCellData(1, "ISU_METHD_INDIRECT") != '1' &&
        dts_IsuInfo.getCellData(1, "ISU_METHD_DIRECT") != '1' &&
        dts_IsuInfo.getCellData(1, "ISU_METHD_PPBOND") != '1') {
        //2006.11.23 add
        $c.win.alert("발행방법을 선택하십시오.");
        return 1;
    }

    //표면이자율확정
    if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == '') {
        $c.win.alert("표면이자율 확정여부를 선택하십시오.");
        return 1;
    } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == 'Y' &&
        dts_IsuInfo.getCellData(1, "COUPN_RT") == '') {
        $c.win.alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
        return 1;
    } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == 'N' &&
        dts_IsuInfo.getCellData(1, "COUPN_RT") != '') {
        if (!window.confirm('표면이자율이 미확정입니다.\n그래도 처리하시겠습니까?')) return 1;
    }

    //류인욱팀장님요구로 사모채도 상장(2006.1130)
    //특수채일경우만 사모가 상장될수가 있고 회사채인경우는 공모로 상장됨
    var msg = '';
    if (dts_IsuInfo.getCellData(1, "ISU_METHD_PPBOND") == '1' &&
        dts_IsuInfo.getCellData(1, "BND_TP_CD") != "AB") {
        //2006.11.23 add
        msg = "" + "발행방법이 사모채로 입력되어있습니다. " + "\n" + "\n사모채는 채권유형이 특수채일때만 입력가능한 항목입니다." + "\n그래도 작업을 계속하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }
    if (dts_IsuInfo.getCellData(1, "BND_INT_PAY_DD_BAS_TP_CD") == '') {
        $c.win.alert("이자일지급기준구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "INT_MMEND_TP_CD") == '') {
        $c.win.alert("이자월말구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "REDMPT_METHD_TP_CD") != '2' &&
        dts_IsuInfo.getCellData(1, "SPLIT_REDMPT_TP_CD") != '') {
        $c.win.alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if ($c.stf.getObjectValue(edt_GrtYd) != '') {
        if ($c.stf.getObjectValue(edt_GrtYd) >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
        if ($c.stf.getObjectValue(edt_ExpRedmptRto) == '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
    }

    //특수채체크
    if ($c.stf.getObjectValue(cmb_BndTpCd) == 'AB') {
        if (dts_IsuInfo.getCellData(1, 'SPECLBND_ISUR_CD') == '') {
            $c.win.alert('특수채 발행기관 코드가 없습니다.');
            return 1;
        }
    } else {
        dts_IsuInfo.setCellData(1, 'SPECLBND_ISUR_CD', '');
    }

    //분할상환체크
    var rowCnt = dts_SplitRedmpt.getTotalRow();
    for (var idx = 1; idx <= rowCnt; idx++) {
        if (dts_SplitRedmpt.getCellData(idx, 'INT_PAY_DD').length != 8) {
            $c.win.alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
            dts_SplitRedmpt.setRowPosition(idx, 0);
            return 1;
        }
    }

    //보장수익률체크
    if ($c.stf.getObjectValue(edt_GrtYd) != '' &&
        $c.stf.getObjectValue(edt_GrtYdStrtDd) == '') {
        $c.win.alert('보장수익률 적용일을 입력하셔야 합니다.');
        return 1;
    }

    //추가수익률체크
    if ($c.stf.getObjectValue(edt_AddYd) != '' &&
        $c.stf.getObjectValue(edt_AddYdStrtDd) == '') {
        $c.win.alert('추가수익률 적용일을 입력하셔야 합니다.');
        return 1;
    }
    if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
    return 0;
};


