scwin.fn_chkInstAlert = function(selObj) {
    if ($c.stf.getObjectValue(selObj) == '') return;
    if ($c.bns.fn_ShowInstAlert(dts_InstCd, $c.cp.getNameValueRow(dts_InstCd, "INST_CD", $c.stf.getObjectValue(selObj))) > 0) {
        $c.stf.setObjectValue(selObj, '');
    }
};



/********************************************** 
 * 함수명   : fn_ExcelDownload
 * 설명       : 엑셀다운로드
 ***********************************************/
scwin.fn_ExcelDownload = function() {
    if (scwin.vRowCount == 0) return;
    showload.style.display = "";

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리
    btn_Excel.setDisabled(true);
    btn_Excel.src = "../img/btn_excelsave_d.gif";
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var dsNm = 'BNS_APPL_ACPT_LIST_EXCEL';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt.excel';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List_excel, dsNm, qryId, param);
    $c.cm.ShowWin(grd_Grid_excel);
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(lbl_ReturnPos, false);
    $c.stf.showObj(grd_Grid_excel, false);
    showload.style.display = "none";

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_List);
    $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
    $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
    $c.bns.BnsPanelToGroupBox(pnl_RelInst);
    $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);

    //접수 임시데이터셋설정

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

    //시장조치구분 설정
    scwin.fn_SetMktactCd();
    //콤보설정
    scwin.fn_SetComboCode();
    //목록조회
    scwin.fn_list_sync();
};
scwin.dts_List_excel_OnLoadCompleted = function(rowcount) {
    showload.style.display = "none";
    $c.data.downloadGridViewExcel(grd_Grid_excel, "일괄상장 연간등록 목록", "", "8");

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 복구
    btn_Excel.setDisabled(false);
    btn_Excel.src = "../img/btn_excelsave.gif";
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.vRowCount = row;
        scwin.vBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        var mktCd = dts_List.getCellData(row, "BND_MKTACT_TP_CD");
        //지방채
        cmb_MunibndTpCd.setDisabled(true);
        if (mktCd == '122') {
            cmb_MunibndTpCd.setDisabled(false);
        }

        //채권유형 국채
        if (mktCd == '112') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'GB');
            cmb_BndTpCd.setDisabled(true);
        }
        //지방채
        else if (mktCd == '122') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'MB');
            cmb_BndTpCd.setDisabled(true);
        }
        //특수채
        else if (mktCd == '132') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'AB');
            cmb_BndTpCd.setDisabled(true);
        }
        //지방공사채
        else if (mktCd == '142') {
            $c.stf.setObjectValue(cmb_BndTpCd, 'CO');
            cmb_BndTpCd.setDisabled(true);
        } else {
            cmb_BndTpCd.setDisabled(false);
        }
        scwin.fn_dtl_sync();
    }
};
